diffs.patch:
Index: index.html
===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,348 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1.0" />
+<title>Call of Duty: Browser Ops — Playground</title>
+<style>
+  * { margin:0; padding:0; box-sizing:border-box; }
+  html,body { width:100%; height:100%; background:#0a0c10; overflow:hidden; font-family:'Arial Black',Arial,sans-serif; user-select:none; }
+  #wrap { position:fixed; inset:0; display:flex; align-items:center; justify-content:center; background:radial-gradient(circle at 50% 30%, #1a2230 0%, #0a0c10 70%); }
+  #game { background:#141a22; border:2px solid #333; box-shadow:0 0 60px rgba(0,0,0,.8); cursor:crosshair; }
+  #hud { position:fixed; inset:0; pointer-events:none; color:#fff; }
+  #topbar { position:absolute; top:12px; left:0; right:0; display:flex; justify-content:center; gap:28px; font-size:15px; letter-spacing:1px; text-shadow:0 2px 4px #000; }
+  #topbar b { color:#ffd34d; }
+  #objective { position:absolute; top:38px; left:0; right:0; text-align:center; font-size:12px; color:#9fe870; letter-spacing:2px; text-shadow:0 1px 3px #000; }
+  #bottomLeft { position:absolute; left:18px; bottom:16px; }
+  #healthWrap { width:280px; height:16px; background:rgba(0,0,0,.6); border:1px solid #555; transform:skewX(-12deg); }
+  #health { height:100%; width:100%; background:linear-gradient(90deg,#e33,#f66); transition:width .15s; }
+  #healthLabel { font-size:12px; margin-top:4px; letter-spacing:2px; color:#ddd; }
+  #bottomRight { position:absolute; right:22px; bottom:12px; text-align:right; }
+  #ammo { font-size:42px; line-height:1; text-shadow:0 2px 6px #000; }
+  #ammo small { font-size:16px; color:#aaa; }
+  #weaponName { font-size:13px; letter-spacing:2px; color:#ffd34d; }
+  #reloadHint { font-size:12px; color:#ff6b6b; min-height:16px; letter-spacing:1px; }
+  #hitmarker { position:absolute; left:50%; top:50%; width:28px; height:28px; margin:-14px 0 0 -14px; opacity:0; }
+  #hitmarker:before,#hitmarker:after { content:''; position:absolute; left:12px; top:0; width:4px; height:28px; background:#fff; transform:rotate(45deg); box-shadow:0 0 4px #000; }
+  #hitmarker:after { transform:rotate(-45deg); }
+  #killfeed { position:absolute; right:18px; top:70px; text-align:right; font-size:12px; font-family:Arial,sans-serif; }
+  #killfeed div { background:rgba(0,0,0,.55); margin:3px 0; padding:4px 8px; border-right:3px solid #ffd34d; }
+  #damageVignette { position:absolute; inset:0; box-shadow:inset 0 0 120px 60px rgba(200,0,0,.85); opacity:0; transition:opacity .2s; }
+  #crosshair { position:absolute; width:6px; height:6px; margin:-3px; background:#0f0; border-radius:50%; box-shadow:0 0 6px #0f0; display:none; }
+  .screen { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; background:rgba(5,8,12,.88); pointer-events:auto; text-align:center; }
+  .screen h1 { font-size:52px; color:#fff; letter-spacing:3px; text-shadow:0 4px 0 #222, 0 0 30px rgba(255,211,77,.3); }
+  .screen h1 span { color:#ffd34d; }
+  .screen p { color:#bbb; font-family:Arial,sans-serif; margin:12px 0; max-width:560px; line-height:1.5; }
+  .screen .controls { color:#888; font-size:13px; font-family:monospace; background:#111; padding:10px 18px; border:1px solid #333; margin:10px 0; }
+  button.big { pointer-events:auto; margin-top:14px; font-family:inherit; font-size:20px; letter-spacing:2px; padding:14px 46px; background:#ffd34d; border:none; cursor:pointer; transform:skewX(-8deg); }
+  button.big:hover { background:#fff; }
+  #waveBanner { position:absolute; top:35%; left:0; right:0; text-align:center; font-size:48px; color:#fff; letter-spacing:6px; opacity:0; text-shadow:0 0 20px #f00; }
+  .hidden { display:none !important; }
+  #sprintBar { width:160px; height:5px; background:rgba(255,255,255,.15); margin-top:6px; }
+  #sprintFill { height:100%; background:#9fe870; width:100%; }
+</style>
+</head>
+<body>
+<div id="wrap"><canvas id="game" width="960" height="600"></canvas></div>
+<div id="hud">
+  <div id="damageVignette"></div>
+  <div id="topbar"><div>SCORE <b id="score">0</b></div><div>KILLS <b id="kills">0</b></div><div>WAVE <b id="wave">1</b></div><div>ENEMIES <b id="foes">0</b></div></div>
+  <div id="objective">◈ MISSION: ELIMINATE ALL HOSTILES — SURVIVE ◈</div>
+  <div id="bottomLeft"><div id="healthWrap"><div id="health"></div></div><div id="healthLabel">HEALTH — REGENERATES IN COVER</div><div id="sprintBar"><div id="sprintFill"></div></div></div>
+  <div id="bottomRight"><div id="weaponName">M4A1 RIFLE [1]</div><div id="ammo">30 <small>/ 120</small></div><div id="reloadHint"></div></div>
+  <div id="killfeed"></div>
+  <div id="hitmarker"></div>
+  <div id="waveBanner">WAVE 1</div>
+  <div id="menu" class="screen">
+    <h1>CALL OF DUTY<span>: BROWSER OPS</span></h1>
+    <p>Playground tactical shooter homage. Hold the compound, survive escalating waves. Health regenerates — use crates as cover. Headshots deal 2x.</p>
+    <div class="controls">WASD move &nbsp;•&nbsp; SHIFT sprint &nbsp;•&nbsp; MOUSE aim &nbsp;•&nbsp; CLICK shoot &nbsp;•&nbsp; R reload &nbsp;•&nbsp; 1/2 weapons &nbsp;•&nbsp; P pause</div>
+    <button class="big" id="startBtn">▶ DEPLOY</button>
+  </div>
+  <div id="over" class="screen hidden">
+    <h1>MISSION <span>FAILED</span></h1>
+    <p id="overStats"></p>
+    <button class="big" id="retryBtn">↻ REDEPLOY</button>
+  </div>
+  <div id="paused" class="screen hidden"><h1>PAUSED</h1><p>Press P to resume</p></div>
+</div>
+<script>
+'use strict';
+/* Call of Duty: Browser Ops — top-down wave shooter. No assets, all procedural. */
+const canvas = document.getElementById('game');
+const ctx = canvas.getContext('2d');
+const W = canvas.width, H = canvas.height;
+
+const el = id => document.getElementById(id);
+const ui = { score: el('score'), kills: el('kills'), wave: el('wave'), foes: el('foes'),
+  health: el('health'), ammo: el('ammo'), weaponName: el('weaponName'), reloadHint: el('reloadHint'),
+  menu: el('menu'), over: el('over'), overStats: el('overStats'), paused: el('paused'),
+  banner: el('waveBanner'), hit: el('hitmarker'), dmg: el('damageVignette'),
+  feed: el('killfeed'), sprint: el('sprintFill') };
+
+const WEAPONS = [
+  { name:'M4A1 RIFLE [1]', mag:30, reserve:150, dmg:34, rof:0.115, spread:0.045, auto:true,  reload:1.2, speed:640, color:'#ffe08a' },
+  { name:'MP5 SMG [2]',    mag:45, reserve:225, dmg:20, rof:0.07,  spread:0.09,  auto:true,  reload:1.5, speed:600, color:'#9fe870' },
+];
+const rand = (a,b)=>a+Math.random()*(b-a);
+const dist2 = (a,b)=>{const dx=a.x-b.x,dy=a.y-b.y;return dx*dx+dy*dy;};
+const clamp = (v,a,b)=>Math.max(a,Math.min(b,v));
+
+let state='menu', paused=false;
+let player, bullets, ebullets, enemies, parts, pickups, covers, floaters;
+let keys={}, mouse={x:W/2,y:H/2,down:false};
+let score=0, kills=0, wave=0, shake=0, lastT=0, fireCd=0, waveDelay=0, bannerT=0, hitT=0;
+
+function newGame(){
+  player={ x:W/2, y:H/2+120, r:13, hp:100, maxhp:100, speed:205, sprint:100, lastDmg:-99,
+    angle:0, wi:0, mag:WEAPONS[0].mag, reserve:WEAPONS[0].reserve, mag2:WEAPONS[1].mag, res2:WEAPONS[1].reserve,
+    reloading:0, kills:0 };
+  bullets=[]; ebullets=[]; enemies=[]; parts=[]; pickups=[]; floaters=[];
+  covers=[
+    {x:120,y:120,w:120,h:26},{x:720,y:120,w:120,h:26},
+    {x:120,y:454,w:120,h:26},{x:720,y:454,w:120,h:26},
+    {x:300,y:250,w:26,h:100},{x:634,y:250,w:26,h:100},
+    {x:430,y:160,w:100,h:26},{x:430,y:414,w:100,h:26},
+  ];
+  score=0; kills=0; wave=0; fireCd=0; shake=0;
+  nextWave();
+  state='play'; paused=false;
+  ui.menu.classList.add('hidden'); ui.over.classList.add('hidden'); ui.paused.classList.add('hidden');
+}
+function nextWave(){
+  wave++; waveDelay=0;
+  const n = 3 + wave*2;
+  for(let i=0;i<n;i++){
+    const edge = Math.floor(rand(0,4));
+    let x,y; if(edge===0){x=rand(30,W-30);y=-20;} else if(edge===1){x=W+20;y=rand(30,H-30);}
+    else if(edge===2){x=rand(30,W-30);y=H+20;} else {x=-20;y=rand(30,H-30);}
+    const fast = Math.random()<Math.min(0.1+wave*0.03,0.4);
+    enemies.push({ x, y, r: fast?10:13, hp: 40+wave*12, maxhp:40+wave*12,
+      speed: fast?rand(95,125)+wave*3 : rand(55,80)+wave*3,
+      fireCd: rand(0.5,1.8), burst:0, fast, wob:rand(0,6.28), score: fast?150:100 });
+  }
+  showBanner('WAVE '+wave);
+  if(wave%3===0) pickups.push({x:rand(200,W-200),y:rand(150,H-150),type:'ammo',t:20});
+  if(wave%2===0) pickups.push({x:rand(200,W-200),y:rand(150,H-150),type:'med',t:20});
+}
+function showBanner(t){ ui.banner.textContent=t; bannerT=2; }
+function feed(msg){ const d=document.createElement('div'); d.textContent=msg; ui.feed.prepend(d); while(ui.feed.children.length>5) ui.feed.lastChild.remove(); setTimeout(()=>d.remove(),4000); }
+
+// --- audio (procedural) ---
+let AC=null; function sfx(kind){ try{
+  AC = AC || new (window.AudioContext||window.webkitAudioContext)();
+  const o=AC.createOscillator(), g=AC.createGain(); o.connect(g); g.connect(AC.destination);
+  const t=AC.currentTime;
+  if(kind==='shoot'){ o.type='square'; o.frequency.setValueAtTime(700,t); o.frequency.exponentialRampToValueAtTime(120,t+0.08); g.gain.setValueAtTime(0.12,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.09); o.start(t); o.stop(t+0.1); }
+  else if(kind==='eshoot'){ o.type='sawtooth'; o.frequency.setValueAtTime(300,t); o.frequency.exponentialRampToValueAtTime(80,t+0.12); g.gain.setValueAtTime(0.06,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.13); o.start(t); o.stop(t+0.14); }
+  else if(kind==='hit'){ o.type='sine'; o.frequency.setValueAtTime(1200,t); g.gain.setValueAtTime(0.1,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.06); o.start(t); o.stop(t+0.07); }
+  else if(kind==='reload'){ o.type='triangle'; o.frequency.setValueAtTime(400,t); o.frequency.setValueAtTime(600,t+0.15); g.gain.setValueAtTime(0.1,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.3); o.start(t); o.stop(t+0.32); }
+  else if(kind==='boom'){ o.type='sawtooth'; o.frequency.setValueAtTime(150,t); o.frequency.exponentialRampToValueAtTime(30,t+0.4); g.gain.setValueAtTime(0.2,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.42); o.start(t); o.stop(t+0.44); }
+}catch(e){} }
+
+function collideCovers(e){
+  for(const c of covers){
+    const nx=clamp(e.x,c.x,c.x+c.w), ny=clamp(e.y,c.y,c.y+c.h);
+    const dx=e.x-nx, dy=e.y-ny, d=Math.hypot(dx,dy);
+    if(d<e.r){ if(d===0){e.y=c.y-e.r; continue;} e.x=nx+dx/d*e.r; e.y=ny+dy/d*e.r; }
+  }
+  e.x=clamp(e.x,-40,W+40); e.y=clamp(e.y,-40,H+40);
+}
+function lineBlocked(ax,ay,bx,by){
+  for(const c of covers){
+    // sample midpoint + endpoints inside rect => blocked
+    const mx=(ax+bx)/2,my=(ay+by)/2;
+    if(mx>c.x&&mx<c.x+c.w&&my>c.y&&my<c.y+c.h) return true;
+  }
+  return false;
+}
+function burst(x,y,color,n,spd){ for(let i=0;i<n;i++) parts.push({x,y,vx:rand(-spd,spd),vy:rand(-spd,spd),life:rand(.2,.6),color,r:rand(1,3)}); }
+
+function shoot(){
+  const wpn=WEAPONS[player.wi];
+  if(player.reloading>0||fireCd>0) return;
+  if(player.mag<=0){ ui.reloadHint.textContent='PRESS R TO RELOAD'; sfx('hit'); startReload(); return; }
+  player.mag--; fireCd=wpn.rof;
+  const a=player.angle+rand(-wpn.spread,wpn.spread);
+  bullets.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*wpn.speed,vy:Math.sin(a)*wpn.speed,life:1.2,dmg:wpn.dmg});
+  burst(player.x+Math.cos(a)*24,player.y+Math.sin(a)*24,'#ffdf6b',4,140);
+  shake=Math.min(shake+2.5,9); sfx('shoot');
+}
+function startReload(){
+  const wpn=WEAPONS[player.wi];
+  const mag = player.wi===0?player.mag:player.mag2, res = player.wi===0?player.reserve:player.res2;
+  if(player.reloading>0||mag>=wpn.mag||res<=0) return;
+  player.reloading=wpn.reload; ui.reloadHint.textContent='RELOADING…'; sfx('reload');
+}
+function finishReload(){
+  const wpn=WEAPONS[player.wi];
+  let mag = player.wi===0?player.mag:player.mag2, res = player.wi===0?player.reserve:player.res2;
+  const need=wpn.mag-mag, take=Math.min(need,res);
+  mag+=take; res-=take;
+  if(player.wi===0){player.mag=mag;player.reserve=res;} else {player.mag2=mag;player.res2=res;}
+  ui.reloadHint.textContent=res<=0?'NO RESERVE AMMO':'';
+}
+
+function update(dt, now){
+  // player move
+  let mx=(keys['d']||keys['arrowright']?1:0)-(keys['a']||keys['arrowleft']?1:0);
+  let my=(keys['s']||keys['arrowdown']?1:0)-(keys['w']||keys['arrowup']?1:0);
+  if(mx&&my){mx*=0.7071;my*=0.7071;}
+  const wantSprint=(keys['shift'])&&player.sprint>1&&(mx||my);
+  const spd=player.speed*(wantSprint?1.55:1);
+  player.x+=mx*spd*dt; player.y+=my*spd*dt;
+  if(wantSprint) player.sprint=Math.max(0,player.sprint-28*dt); else player.sprint=Math.min(100,player.sprint+16*dt);
+  collideCovers(player);
+  player.x=clamp(player.x,player.r,W-player.r); player.y=clamp(player.y,player.r,H-player.r);
+  player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x);
+  // regen (CoD style) after 3s no damage
+  if(now-player.lastDmg>3&&player.hp<player.maxhp) player.hp=Math.min(player.maxhp,player.hp+26*dt);
+  if(player.reloading>0){ player.reloading-=dt; if(player.reloading<=0) finishReload(); }
+  fireCd-=dt;
+  if(mouse.down){ const wpn=WEAPONS[player.wi]; if(wpn.auto) shoot(); }
+  // bullets
+  for(let i=bullets.length-1;i>=0;i--){ const b=bullets[i]; b.x+=b.vx*dt; b.y+=b.vy*dt; b.life-=dt;
+    let dead=b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H;
+    if(!dead) for(const c of covers){ if(b.x>c.x&&b.x<c.x+c.w&&b.y>c.y&&b.y<c.y+c.h){ burst(b.x,b.y,'#8899aa',5,120); dead=true; break; } }
+    if(!dead) for(let j=enemies.length-1;j>=0;j--){ const e=enemies[j];
+      if(dist2(b,e)<(e.r+3)*(e.r+3)){ let d=b.dmg; burst(b.x,b.y,'#ff4d4d',8,180);
+        e.hp-=d; hitT=0.12; sfx('hit');
+        floaters.push({x:e.x,y:e.y-16,txt:'-'+Math.round(d),life:0.6,color:'#fff'});
+        dead=true;
+        if(e.hp<=0){ enemies.splice(j,1); kills++; score+=e.score; player.kills++;
+          burst(e.x,e.y,'#ff2222',18,220); sfx('boom'); shake=Math.min(shake+3,10);
+          feed('☠ Hostile down +'+e.score);
+          if(Math.random()<0.18) pickups.push({x:e.x,y:e.y,type:Math.random()<0.6?'ammo':'med',t:15});
+        }
+        break; } }
+    if(dead) bullets.splice(i,1);
+  }
+  // enemies AI
+  for(const e of enemies){
+    e.wob+=dt*3;
+    const a=Math.atan2(player.y-e.y,player.x-e.x)+Math.sin(e.wob)*0.25;
+    const want = Math.hypot(player.x-e.x,player.y-e.y);
+    const holdR = e.fast?60:170;
+    let vx=0,vy=0;
+    if(want>holdR){ vx=Math.cos(a)*e.speed; vy=Math.sin(a)*e.speed; }
+    else { vx=Math.cos(a+1.57)*e.speed*0.5; vy=Math.sin(a+1.57)*e.speed*0.5; }
+    e.x+=vx*dt; e.y+=vy*dt; collideCovers(e);
+    e.fireCd-=dt;
+    if(e.fireCd<=0&&want<420&&!lineBlocked(e.x,e.y,player.x,player.y)){
+      const sa=Math.atan2(player.y-e.y,player.x-e.x)+rand(-0.12,0.12);
+      ebullets.push({x:e.x,y:e.y,vx:Math.cos(sa)*300,vy:Math.sin(sa)*300,life:2,dmg:7+wave*1.2});
+      sfx('eshoot'); e.fireCd=rand(0.9,2.2)-Math.min(wave*0.05,0.7);
+    }
+  }
+  for(let i=ebullets.length-1;i>=0;i--){ const b=ebullets[i]; b.x+=b.vx*dt; b.y+=b.vy*dt; b.life-=dt;
+    let dead=b.life<=0;
+    if(!dead) for(const c of covers){ if(b.x>c.x&&b.x<c.x+c.w&&b.y>c.y&&b.y<c.y+c.h){dead=true;break;} }
+    if(!dead&&dist2(b,player)<(player.r+3)*(player.r+3)){
+      player.hp-=b.dmg; player.lastDmg=now; shake=Math.min(shake+4,12); burst(player.x,player.y,'#ff2222',6,160); dead=true;
+      ui.dmg.style.opacity=0.9; setTimeout(()=>ui.dmg.style.opacity=0,180);
+      if(player.hp<=0){ player.hp=0; gameOver(); return; }
+    }
+    if(dead) ebullets.splice(i,1);
+  }
+  // pickups
+  for(let i=pickups.length-1;i>=0;i--){ const p=pickups[i]; p.t-=dt;
+    if(p.t<=0){pickups.splice(i,1);continue;}
+    if(dist2(p,player)<28*28){
+      if(p.type==='ammo'){ player.reserve+=60; if(player.wi!==0)player.res2+=0; else player.reserve+=0; WEAPONS[1].reserve+=0; player.res2+=45; feed('+ AMMO'); }
+      else { player.hp=Math.min(player.maxhp,player.hp+50); feed('+ HEALTH'); }
+      pickups.splice(i,1);
+    }
+  }
+  for(let i=parts.length-1;i>=0;i--){ const p=parts[i]; p.x+=p.vx*dt; p.y+=p.vy*dt; p.vx*=0.92; p.vy*=0.92; p.life-=dt; if(p.life<=0)parts.splice(i,1); }
+  for(let i=floaters.length-1;i>=0;i--){ const f=floaters[i]; f.y-=30*dt; f.life-=dt; if(f.life<=0)floaters.splice(i,1); }
+  if(enemies.length===0){ waveDelay+=dt; if(waveDelay>1.6) nextWave(); }
+  shake=Math.max(0,shake-30*dt); bannerT-=dt; hitT-=dt;
+}
+
+function render(){
+  ctx.save();
+  if(shake>0) ctx.translate(rand(-shake,shake),rand(-shake,shake));
+  // ground
+  ctx.fillStyle='#1b2230'; ctx.fillRect(-20,-20,W+40,H+40);
+  ctx.strokeStyle='rgba(255,255,255,0.05)'; ctx.lineWidth=1;
+  for(let x=0;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
+  for(let y=0;y<H;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
+  // pickups
+  for(const p of pickups){ ctx.fillStyle=p.type==='ammo'?'#ffd34d':'#4dff88';
+    ctx.fillRect(p.x-9,p.y-9,18,18); ctx.fillStyle='#000'; ctx.font='bold 12px Arial'; ctx.textAlign='center';
+    ctx.fillText(p.type==='ammo'?'A':'+',p.x,p.y+4); }
+  // covers
+  for(const c of covers){ ctx.fillStyle='#3a4356'; ctx.fillRect(c.x,c.y,c.w,c.h);
+    ctx.fillStyle='#525f7a'; ctx.fillRect(c.x,c.y,c.w,5); ctx.strokeStyle='#111'; ctx.strokeRect(c.x,c.y,c.w,c.h); }
+  // enemies
+  for(const e of enemies){ const a=Math.atan2(player.y-e.y,player.x-e.x);
+    ctx.fillStyle='rgba(0,0,0,.35)'; ctx.beginPath(); ctx.ellipse(e.x+3,e.y+4,e.r,e.r*0.7,0,0,7); ctx.fill();
+    ctx.save(); ctx.translate(e.x,e.y); ctx.rotate(a);
+    ctx.fillStyle=e.fast?'#c0392b':'#8e2f2f'; ctx.beginPath(); ctx.arc(0,0,e.r,0,7); ctx.fill();
+    ctx.fillStyle='#222'; ctx.fillRect(4,-3,e.r+6,6);
