const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: '/tmp/cod2-menu.png' });
  await page.click('#startBtn');
  await page.waitForTimeout(2000);
  await page.mouse.move(900, 300);
  await page.keyboard.down('d');
  await page.mouse.down();
  await page.waitForTimeout(1200);
  await page.mouse.up();
  await page.keyboard.up('d');
  await page.screenshot({ path: '/tmp/cod2-play.png' });
  // ADS test (right click hold)
  await page.mouse.move(640, 200);
  await page.mouse.down({ button: 'right' });
  await page.mouse.down();
  await page.waitForTimeout(1000);
  await page.screenshot({ path: '/tmp/cod2-ads.png' });
  await page.mouse.up();
  await page.mouse.up({ button: 'right' });
  // switch to shotgun + fire
  await page.keyboard.press('3');
  await page.mouse.move(800, 400);
  await page.mouse.down(); await page.waitForTimeout(300); await page.mouse.up();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/cod2-shotgun.png' });
  const state = await page.evaluate(() => ({
    score: document.getElementById('score').textContent,
    wave: document.getElementById('wave').textContent,
    foes: document.getElementById('foes').textContent,
    ammo: document.getElementById('ammo').textContent,
    wname: document.getElementById('weaponName').textContent
  }));
  console.log('STATE ' + JSON.stringify(state));
  // force game over to verify screen
  await page.evaluate(() => { window.scrollTo(0,0); });
  const over = await page.evaluate(() => {
    // simulate lethal damage by evaluating internals? fallback: check gameOver exists via spamming enemies is hard; just report alive
    return document.getElementById('over').className;
  });
  console.log('OVERCLASS ' + over);
  console.log('ERRORS ' + JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error('FATAL ' + e.message); process.exit(1); });

