input.content:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/cod3-menu.png' });
  await page.click('#startBtn');
  await page.waitForTimeout(1200);
  // aimbot: aim at nearest enemy each 100ms and hold fire for 6s
  const t0 = Date.now();
  await page.mouse.down();
  while (Date.now() - t0 < 6000) {
    try {
      const box = await page.evaluate(() => {
        const c = document.getElementById('game'); const r = c.getBoundingClientRect();
        return { l: r.left, t: r.top, w: r.width, h: r.height };
      });
      const tgt = await page.evaluate(() => {
        // reach into game scope via canvas? enemies not exposed; approximate: find red pixels? fallback sweep
        return null;
      });
      // sweep aim in circles to guarantee hits over time
      const a = (Date.now() - t0) / 300;
      const cx = box.l + box.w / 2, cy = box.t + box.h / 2;
      await page.mouse.move(cx + Math.cos(a) * 220, cy + Math.sin(a) * 220, { steps: 3 });
    } catch (e) {}
    await page.waitForTimeout(120);
  }
  await page.mouse.up();
  const s1 = await page.evaluate(() => ({ score: score.textContent, kills: kills.textContent, wave: wave.textContent, foes: foes.textContent, ammo: ammo.textContent }));
  // NOTE: page vars are const in closure; use DOM directly
  const state = await page.evaluate(() => ({ score: document.getElementById('score').textContent, kills: document.getElementById('kills').textContent, wave: document.getElementById('wave').textContent, foes: document.getElementById('foes').textContent, ammo: document.getElementById('ammo').textContent, feed: document.getElementById('killfeed').innerText.slice(0,120) }));
  console.log('COMBAT ' + JSON.stringify(state));
  await page.screenshot({ path: '/tmp/cod3-combat.png' });
  console.log('ERRORS ' + JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error('FATAL ' + e.message); process.exit(1); });

