const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(600);
  await page.click('#startBtn');
  await page.waitForTimeout(800);
  await page.mouse.down();
  const t0 = Date.now();
  let last = null;
  while (Date.now() - t0 < 15000) {
    const g = await page.evaluate(() => window.__game ? window.__game() : null);
    if (!g) break;
    last = { score: g.score, kills: g.kills, wave: g.wave, foes: g.foes.length, hp: Math.round(g.player.hp), mag: g.player.mag, res: g.player.res };
    if (g.state !== 'play') break;
    if (g.foes.length) {
      // nearest foe to player in game coords -> screen coords
      let best = null, bd = 1e18;
      for (const f of g.foes) { const d = (f.x - g.player.x) ** 2 + (f.y - g.player.y) ** 2; if (d < bd) { bd = d; best = f; } }
      const sx = g.canvas.l + (best.x / 960) * g.canvas.w;
      const sy = g.canvas.t + (best.y / 600) * g.canvas.h;
      await page.mouse.move(sx, sy, { steps: 2 });
    }
    await page.waitForTimeout(90);
    if (g.wave >= 2 || g.kills >= 3) break;
  }
  await page.mouse.up();
  console.log('AIMBOT ' + JSON.stringify(last));
  await page.screenshot({ path: '/tmp/cod4-aimbot.png' });
  // game-over check: hurt player via long exposure? just report state
  const st = await page.evaluate(() => ({ over: document.getElementById('over').className, feed: document.getElementById('killfeed').innerText.slice(0, 200) }));
  console.log('OVER ' + JSON.stringify(st));
  console.log('ERRORS ' + JSON.stringify(errors.slice(0, 10)));
  await browser.close();
})().catch(e => { console.error('FATAL ' + e.message); process.exit(1); });

